svg.script:

(function() {
  const DB_NAME = "EaglercraftCacheDB";
  const STORE_NAME = "game_files";

  const statusText = document.getElementById("statusText");
  const launchGroup = document.getElementById("launchGroup");
  const commitPresetGroup = document.getElementById("commitPresetGroup");
  const clearGroup = document.getElementById("clearGroup");
  const commitInput = document.getElementById("commitInput");

  function updateStatus(msg) {
    if (statusText) statusText.textContent = msg;
  }

  function getUrls(commitRef) {
    const ref = (commitRef && commitRef.trim()) ? commitRef.trim() : "main";
    return {
      ref: ref,
      rawUrl: "https://media.githubusercontent.com/media/aerograde/eagle-26.2/" + ref + "/dist/direct-connect.html",
      baseUrl: "https://media.githubusercontent.com/media/aerograde/eagle-26.2/" + ref + "/dist/"
    };
  }

  function openDB() {
    return new Promise((resolve, reject) => {
      const req = indexedDB.open(DB_NAME);

      req.onupgradeneeded = (e) => {
        const db = e.target.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME);
        }
      };

      req.onsuccess = () => {
        const db = req.result;
        if (db.objectStoreNames.contains(STORE_NAME)) {
          resolve(db);
        } else {
          const nextVersion = (db.version || 1) + 1;
          db.close();
          const upReq = indexedDB.open(DB_NAME, nextVersion);
          upReq.onupgradeneeded = (e) => {
            const uDb = e.target.result;
            if (!uDb.objectStoreNames.contains(STORE_NAME)) {
              uDb.createObjectStore(STORE_NAME);
            }
          };
          upReq.onsuccess = () => resolve(upReq.result);
          upReq.onerror = () => reject(upReq.error);
        }
      };

      req.onerror = () => reject(req.error);
    });
  }

  async function getStoredGame(db, key) {
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, "readonly");
      const store = tx.objectStore(STORE_NAME);
      const req = store.get(key);
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
  }

  async function saveGame(db, key, content) {
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, "readwrite");
      const store = tx.objectStore(STORE_NAME);
      const req = store.put(content, key);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  }

  async function clearStoredGame(db) {
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, "readwrite");
      const store = tx.objectStore(STORE_NAME);
      const req = store.clear();
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  }

  function launchInAboutBlank(htmlContent, baseUrl) {
    const win = window.open("about:blank", "_blank");
    if (!win) {
      updateStatus("Pop-up blocked! Allow pop-ups and try again.");
      return;
    }

    let processedHtml = htmlContent;
    if (!/<base\s/i.test(processedHtml)) {
      processedHtml = '<base href="' + baseUrl + '">' + processedHtml;
    }

    win.document.open();
    win.document.write(processedHtml);
    win.document.close();
    updateStatus("Launched successfully!");
  }

  async function handleLaunch(commitRef) {
    try {
      const { ref, rawUrl, baseUrl } = getUrls(commitRef);
      const gameKey = "eaglercraft_index_" + ref;

      updateStatus("Opening IndexedDB (" + ref + ")...");
      const db = await openDB();

      updateStatus("Checking cached version for [" + ref + "]...");
      let cachedHtml = await getStoredGame(db, gameKey);

      if (cachedHtml && !cachedHtml.trim().startsWith("version https://git-lfs.github.com/spec/v1")) {
        updateStatus("Loaded commit [" + ref + "] from cache! Launching...");
        launchInAboutBlank(cachedHtml, baseUrl);
      } else {
        updateStatus("Downloading commit [" + ref + "] (~89 MB)...");
        const response = await fetch(rawUrl);
        if (!response.ok) {
          throw new Error("HTTP " + response.status + " - Commit '" + ref + "' not found");
        }
        const text = await response.text();

        if (text.trim().startsWith("version https://git-lfs.github.com/spec/v1")) {
          throw new Error("Received LFS pointer instead of file.");
        }

        updateStatus("Saving to IndexedDB...");
        await saveGame(db, gameKey, text);

        updateStatus("Launching...");
        launchInAboutBlank(text, baseUrl);
      }
    } catch (err) {
      console.error(err);
      updateStatus("Error: " + err.message);
    }
  }

  async function handleClear() {
    try {
      updateStatus("Opening IndexedDB...");
      const db = await openDB();
      updateStatus("Clearing all stored cache...");
      await clearStoredGame(db);
      updateStatus("Cache cleared successfully!");
    } catch (err) {
      console.error(err);
      updateStatus("Error clearing cache: " + err.message);
    }
  }

  if (launchGroup) {
    launchGroup.addEventListener("click", function() {
      const targetCommit = commitInput ? commitInput.value : "56ec29f";
      handleLaunch(targetCommit);
    });
  }

  if (commitPresetGroup) {
    commitPresetGroup.addEventListener("click", function() {
      if (commitInput) commitInput.value = "56ec29f";
      handleLaunch("56ec29f");
    });
  }

  if (clearGroup) {
    clearGroup.addEventListener("click", handleClear);
  }
})();
